import type { ConnectorDefinition } from '../registry'

/**
 * Azure OpenAI through the v1 GA API (https://{resource}.openai.azure.com/openai/v1/…):
 * no api-version parameter; the deployment name goes in the body as `model`.
 * The connector's Deployment Name fills the deployment_name input when a
 * call leaves it empty.
 *
 * base_url stays the bare resource host so references generated by older
 * versions of this connector (/openai/deployments/{{deployment_name}}/…?api-version=…)
 * keep working; the API Version field only serves those legacy references.
 */
export const azureOpenaiConnector: ConnectorDefinition = {
  key: 'azure_openai',
  name: 'Azure OpenAI',
  description: 'OpenAI models hosted on Microsoft Azure with enterprise security',
  category: 'ai',
  icon: 'Cloud',
  color: '#0078D4',
  docsUrl: 'https://learn.microsoft.com/en-us/azure/ai-foundry/openai/api-version-lifecycle',
  fields: [
    {
      key: 'resource_name',
      label: 'Resource Name',
      type: 'text',
      placeholder: 'my-openai-resource',
      required: true,
      validation: { type: 'azure_resource_name' },
      helpText: 'Azure OpenAI resource name (the part before .openai.azure.com)',
    },
    {
      key: 'deployment_name',
      label: 'Deployment Name',
      type: 'text',
      placeholder: 'gpt-4o',
      required: true,
      helpText: 'Model deployment name configured in Azure; used when a call does not name one',
    },
    {
      key: 'api_version',
      label: 'API Version (legacy)',
      type: 'text',
      placeholder: '2024-10-21',
      defaultValue: '2024-10-21',
      helpText: 'Only used by references created before the v1 API (which needs no version).',
    },
  ],
  credentialFields: [
    { key: 'api_key', label: 'API Key', type: 'password', placeholder: '', required: true, helpText: 'Azure OpenAI API Key (Keys and Endpoint in the Azure portal)' },
  ],
  referenceTemplates: [
    {
      key: 'chat_completion',
      name: 'Chat Completion',
      description: 'Generate a chat completion via Azure OpenAI (v1 API)',
      method: 'POST',
      pathTemplate: '/openai/v1/chat/completions',
      headers: { 'Content-Type': 'application/json' },
      bodyTemplate: '{"model":"{{deployment_name}}","messages":[{"role":"system","content":"{{system_prompt}}"},{"role":"user","content":"{{user_message}}"}],"max_completion_tokens":{{max_tokens}},"temperature":{{temperature}}}',
      inputs: [
        { name: 'user_message', type: 'string', required: true, description: 'User message' },
        { name: 'system_prompt', type: 'string', required: false, description: 'System prompt', defaultValue: 'You are a helpful assistant.' },
        { name: 'deployment_name', type: 'string', required: false, description: 'Deployment name (defaults to the connector\'s deployment)' },
        { name: 'max_tokens', type: 'number', required: false, description: 'Maximum completion tokens (sent as max_completion_tokens)', defaultValue: '1024' },
        { name: 'temperature', type: 'number', required: false, description: 'Temperature 0-2 (leave empty for reasoning models, which only accept the default)' },
      ],
      outputs: [
        { name: 'choices[0].message.content', type: 'string' },
        { name: 'choices', type: 'array' },
        { name: 'usage', type: 'object' },
        { name: 'model', type: 'string' },
      ],
    },
    {
      key: 'create_embedding',
      name: 'Create Embedding',
      description: 'Generate vector embeddings for text with an embeddings deployment (v1 API)',
      method: 'POST',
      pathTemplate: '/openai/v1/embeddings',
      headers: { 'Content-Type': 'application/json' },
      bodyTemplate: '{"model":"{{embedding_deployment}}","input":"{{text}}"}',
      inputs: [
        { name: 'text', type: 'string', required: true, description: 'Text to embed' },
        { name: 'embedding_deployment', type: 'string', required: true, description: 'Embeddings deployment name (e.g. text-embedding-3-small)' },
      ],
      outputs: [
        { name: 'data[0].embedding', type: 'array' },
        { name: 'usage', type: 'object' },
      ],
    },
  ],
  buildIntegrationConfig: (config, credentials) => ({
    base_url: `https://${config.resource_name}.openai.azure.com`,
    auth_type: 'api_key',
    auth_config: { key_name: 'api-key', key_value: credentials.api_key, add_to: 'header' },
  }),
}
